import type { TestCase } from "../tests/types";

export type CaseResult = {
  name: string;
  status: "running" | "pass" | "fail";
  lines: string[];
  expected: string[];
  error?: string;
  ms: number;
};

/** Runs one end-to-end case and compares its printed lines with the expected ones. */
export async function runCase(c: TestCase): Promise<CaseResult> {
  const lines: string[] = [];
  const start = Date.now();
  const print = (...args: unknown[]) => lines.push(args.map((a) => String(a)).join(" "));
  let error: string | undefined;
  try {
    c.run(c.module, print, (x: unknown) => x, {});
  } catch (e) {
    error = e instanceof Error ? `${e.name}: ${e.message}` : String(e);
  }
  // Async cases print as their promises settle.
  const deadline = Date.now() + 10000;
  while (!error && lines.length < c.expected.length && Date.now() < deadline) {
    await new Promise<void>((r) => setTimeout(() => r(), 20));
  }
  await new Promise<void>((r) => setTimeout(() => r(), 50));
  const pass =
    !error && lines.length === c.expected.length && lines.every((l, i) => l === c.expected[i]);
  return {
    name: c.name,
    status: pass ? "pass" : "fail",
    lines,
    expected: c.expected,
    error,
    ms: Date.now() - start,
  };
}
